    Unresistable = 274, Lifetap = 37, Physical = 177, crit = 177 }
M.by_id = {}
M.custom, M.stock = {}, {}
for _, n in ipairs(M.list) do M.by_id[n.id] = n; if n.custom then M.custom[#M.custom + 1] = n else M.stock[#M.stock + 1] = n end end
M.COUNT = #M.list
M.CUSTOM_COUNT, M.STOCK_COUNT = #M.custom, #M.stock
return M
